const $=s=>document.querySelector(s), key='bora.pilot.v1';
let data;try{data=JSON.parse(localStorage.getItem(key))||{}}catch{data={}}
let active='one', quiz=null, step=0;
const empty=()=>({name:'',goal:'Общение с бразильцами',minutes:'15',experience:'С нуля',onboarded:false,diagnosis:null,attempts:[],completed:false,draft:''});
const user=()=>data[active]||(data[active]=empty());
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem(key,JSON.stringify(data))}catch{alert('Не удалось сохранить прогресс. Проверь доступ к хранилищу браузера.')}}
const questions=[
{skill:'Слова и приветствия',q:'Что означает «Oi!»?',options:['Привет!','Спасибо!','До завтра!'],answer:0,why:'Oi — обычное дружеское приветствие в Бразилии.'},
{skill:'Понимание фразы',q:'«Eu moro no Brasil» — что сообщает человек?',options:['Он едет в Бразилию','Он живёт в Бразилии','Он родился в Бразилии'],answer:1,why:'Eu — я, moro — живу, no Brasil — в Бразилии.'},
{skill:'Базовая грамматика',q:'Как сказать «Я сейчас дома»?',options:['Eu sou em casa.','Eu estou em casa.','Eu tenho em casa.'],answer:1,why:'Для местонахождения человека используем estar: Eu estou em casa.'},
{skill:'События в прошлом',q:'«Ontem eu fui ao mercado.» Когда человек ходил в магазин?',options:['Вчера','Каждый день','Завтра'],answer:0,why:'Ontem означает «вчера», fui — форма прошедшего времени глагола ir.'},
{skill:'Более сложные конструкции',q:'Выбери подходящий вариант: «Se eu tivesse tempo, …»',options:['eu vou estudar.','eu estudaria mais.','eu estudei ontem.'],answer:1,why:'Здесь описана воображаемая ситуация: «Если бы у меня было время, я бы учился больше».'}
];
function home(){const u=user();return `<section class="hero"><div class="hero-copy"><div class="eyebrow">Português do Brasil · маленькими шагами</div><h1>${u.onboarded?`Oi, ${esc(u.name)}!<br>Продолжим?`:'Ближе к Бразилии.<br>С каждой фразой.'}</h1><p>Понимай, как устроен язык. Говори о том, что важно тебе. Учись в своём темпе.</p><a class="btn yellow" href="#${!u.onboarded?'start':!u.diagnosis?'diagnosis':'lesson'}">${!u.onboarded?'Начать знакомство':!u.diagnosis?'Узнать стартовый уровень':'Продолжить занятие'} ↗</a><p class="small" style="margin-top:17px">Без спешки. Без сложных объяснений.</p></div><div class="hero-photo" role="img" aria-label="Рио-де-Жанейро на закате"><span class="photo-caption">Rio de Janeiro, Brasil ☀</span></div></section><div class="section-head"><h2>Твой следующий шаг</h2><span class="small">Um passo de cada vez</span></div><section class="grid"><article class="card green"><span class="number">01 / ЗНАКОМСТВО</span><h3>Начнём с тебя</h3><p>Твоя цель, опыт и удобное время занятий.</p><a href="#start">${u.onboarded?'Изменить профиль':'Рассказать о себе'} →</a></article><article class="card"><span class="number">02 / СТАРТОВАЯ ТОЧКА</span><h3>Что уже получается?</h3><p>Короткая проверка с изменением сложности. Можно отвечать «Не знаю».</p><a href="#diagnosis">${u.diagnosis?'Посмотреть и пройти снова':'Пройти диагностику'} →</a></article><article class="card city"><span class="number">03 / ПЕРВЫЙ РАЗГОВОР</span><h3>Oi! Tudo bem?</h3><p>Познакомимся и разберём первые бразильские фразы.</p><a href="#lesson">Открыть занятие →</a></article></section><div class="notice">Это работающий прототип учебного сценария. GigaChat и записи носителей ещё не подключены. Выбор профиля — не защищённая авторизация.</div>`}
function start(){const u=user();return `<div class="narrow"><a class="back" href="#home">← На главную</a><div class="panel"><div class="eyebrow">Давай познакомимся</div><h1>Твой язык.<br>Твой маршрут.</h1><p>Ответы сохранятся только для выбранного профиля.</p><form id="onboarding"><label>Как тебя называть?<input name="name" maxlength="40" required value="${esc(u.name)}" autocomplete="given-name"></label><label>Для чего учишь португальский?<select name="goal">${['Общение с бразильцами','Общение и подготовка к Celpe-Bras','Пока определяюсь'].map(x=>`<option ${u.goal===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Какой у тебя опыт?<select name="experience">${['С нуля','Знаю отдельные слова','Могу немного общаться'].map(x=>`<option ${u.experience===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Сколько минут в день удобно заниматься?<select name="minutes">${['10','15','25'].map(x=>`<option ${u.minutes===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn">Сохранить и продолжить →</button></form></div></div>`}
function diagnosis(){if(!user().onboarded)return `<div class="narrow panel"><h1>Сначала познакомимся</h1><p>Выбери цель и расскажи о своём опыте.</p><a class="btn" href="#start">Заполнить профиль</a></div>`;if(!quiz)return `<div class="narrow panel"><div class="eyebrow">Диагностика · до 5 вопросов</div><h1>Найдём точку старта</h1><p>Начнём с простого. После двух уверенных ответов перейдём к более сложному вопросу. При двух затруднениях остановимся.</p><p>Эта короткая проверка не определяет официальный уровень и не оценивает устную речь.</p>${user().diagnosis?`<div class="notice">Предыдущий результат: ${esc(user().diagnosis.summary)}</div>`:''}<button class="btn" id="begin-quiz">Начать проверку</button></div>`;const q=questions[quiz.index];return `<div class="narrow panel"><div class="eyebrow">Вопрос ${quiz.results.length+1} · ${esc(q.skill)}</div><progress max="5" value="${quiz.results.length}" aria-label="Пройдено вопросов"></progress><h2 style="margin-top:25px">${q.q}</h2><div class="options">${q.options.map((x,i)=>`<button class="option" data-answer="${i}">${esc(x)}</button>`).join('')}<button class="option" data-answer="-1">Пока не знаю</button></div></div>`}
function result(){const d=user().diagnosis;return `<div class="narrow panel"><div class="eyebrow">Точка старта сохранена</div><h1>Теперь есть ориентир</h1><p>${esc(d.summary)}</p>${d.results.map(r=>`<div class="feedback ${r.correct?'':'bad'}"><strong>${esc(questions[r.index].skill)}: ${r.correct?'получилось':'нужна практика'}</strong><br>${esc(questions[r.index].why)}</div>`).join('')}<p class="small">Это предварительный учебный результат, а не оценка CEFR или Celpe-Bras. Проверка понимания на слух и свободных ответов появится позже.</p><a class="btn" href="#lesson">Начать первое занятие →</a></div>`}
const pages=[
{title:'Первое «привет»',body:'В Бразилии можно начать дружеский разговор с Oi! Это короткое «Привет!». Чтобы спросить «Как дела?», добавь Tudo bem?',pt:'Oi! Tudo bem?',ru:'Привет! Как дела?',why:'Буквально tudo bem — «всё хорошо». С вопросительной интонацией это вопрос, а как ответ — «всё хорошо».',q:'Что подходит для дружеского начала разговора?',options:['Oi! Tudo bem?','Até amanhã!','Obrigado!'],answer:0},
{title:'Как представиться',body:'Eu означает «я», sou — «есть / являюсь» в этой фразе. По-русски мы говорим «Я Анна», а по-португальски оставляем глагол: Eu sou a Ana.',pt:'Oi! Eu sou a Ana.',ru:'Привет! Я Анна.',why:'Артикль a перед именем встречается во многих регионах Бразилии. Форма Eu sou Ana тоже возможна. Для имени мужчины в такой конструкции используется o.',q:'Как представиться, если тебя зовут Ана?',options:['Eu estou Ana.','Eu sou a Ana.','Eu tenho Ana.'],answer:1},
{title:'Откуда ты?',body:'Чтобы сказать, откуда ты, используем sou de. Например, Eu sou de Moscou — «Я из Москвы». Для России: Eu sou da Rússia.',pt:'Eu sou da Rússia.',ru:'Я из России.',why:'Da получается из de + a. С названием Rússia обычно употребляется артикль a. Поэтому здесь da Rússia.',q:'Как сказать «Я из России»?',options:['Eu moro Rússia.','Eu estou Rússia.','Eu sou da Rússia.'],answer:2}
];
function lesson(){if(!user().onboarded)return `<div class="narrow panel"><h1>Начнём со знакомства</h1><a class="btn" href="#start">Заполнить профиль</a></div>`;const p=pages[step];return `<div class="narrow"><a class="back" href="#home">← Мой путь</a><div class="panel"><div class="eyebrow">Знакомство · шаг ${step+1} из 3</div><progress value="${step}" max="3" aria-label="Шаг занятия"></progress><h1 style="margin-top:24px">${p.title}</h1><p>${p.body}</p><div class="example"><strong lang="pt-BR">${p.pt}</strong><p>${p.ru}</p><span class="small">Аудио носителя ещё не добавлено</span></div><details><summary>Почему так устроено?</summary><p>${p.why}</p></details><h3 style="margin-top:24px">${p.q}</h3><div class="options">${p.options.map((x,i)=>`<button class="option" data-lesson-answer="${i}">${x}</button>`).join('')}</div><div id="feedback" role="status" aria-live="polite"></div><label for="draft">Твоя фраза или вопрос к объяснению</label><textarea id="draft" placeholder="Попробуй представиться по-португальски…">${esc(user().draft||'')}</textarea><p class="small">Сохраняется как заметка. Свободная проверка через GigaChat пока недоступна.</p><div class="row">${step?'<button class="btn alt" id="previous">← Назад</button>':''}<button class="btn" id="next" disabled>${step===2?'Завершить занятие':'Следующий шаг →'}</button></div></div></div>`}
function progress(){const u=user(),correct=u.attempts.filter(a=>a.correct).length;return `<div class="narrow"><div class="eyebrow">Твой прогресс</div><h1>Каждый шаг считается.</h1><section class="grid"><div class="card"><div class="stat">${u.completed?1:0}</div><p>Занятий завершено</p></div><div class="card"><div class="stat">${u.attempts.length}</div><p>Попыток в упражнениях</p></div><div class="card green"><div class="stat">${correct}</div><p>Правильных ответов</p></div></section><div class="panel" style="margin-top:24px"><h2>Что уже проверили</h2><p>${u.diagnosis?esc(u.diagnosis.summary):'Диагностика ещё не пройдена.'}</p><p>${u.completed?'Пройдено занятие «Знакомство». Чтобы закрепить навык, повтори его позже без подсказок.':'Начни со знакомства и первого небольшого занятия.'}</p><a class="btn" href="#lesson">${u.completed?'Повторить занятие':'Перейти к занятию'}</a><h3 style="margin-top:25px">Последние попытки</h3>${u.attempts.slice(-6).reverse().map(a=>`<p class="small">${esc(pages[a.step].title)} · ${a.correct?'верно':'ошибка'} · ${new Date(a.at).toLocaleString('ru-RU')}</p>`).join('')||'<p class="small">Здесь появятся результаты упражнений.</p>'}</div><div class="notice">Один завершённый урок не означает освоения языка. Говорение и произношение в этом прототипе не оценивались.</div></div>`}
function render(){const route=location.hash.slice(1)||'home';$('#app').innerHTML=({home,start,diagnosis,lesson,progress,result:()=>user().diagnosis?result():diagnosis()}[route]||home)();$('#profile').options[0].textContent=data.one?.name||'Профиль 1';$('#profile').options[1].textContent=data.two?.name||'Профиль 2';bind()}
function bind(){const f=$('#onboarding');if(f)f.onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));if(!v.name.trim())return;Object.assign(user(),v,{name:v.name.trim(),onboarded:true});save();location.hash='diagnosis'};if($('#begin-quiz'))$('#begin-quiz').onclick=()=>{quiz={index:0,results:[]};render()};document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{const i=quiz.index,correct=Number(b.dataset.answer)===questions[i].answer;quiz.results.push({index:i,correct,answer:Number(b.dataset.answer)});const failures=quiz.results.filter(r=>!r.correct).length;if(failures>=2||i===4){const n=quiz.results.filter(r=>r.correct).length;user().diagnosis={at:new Date().toISOString(),results:quiz.results,summary:n===0?'Начнём с самых первых слов и фраз.':n<3?'Некоторые основы уже знакомы. Укрепим простые фразы и построение предложений.':'Базовые задания получаются. Дальше нужно проверить самостоятельное письмо и понимание на слух.'};save();quiz=null;location.hash='result'}else{quiz.index=Math.min(4,i+(correct&&quiz.results.length===2&&quiz.results.every(r=>r.correct)?2:1));render()}});document.querySelectorAll('[data-lesson-answer]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.lessonAnswer)===pages[step].answer;user().attempts.push({step,correct,at:new Date().toISOString()});save();$('#feedback').className='feedback'+(correct?'':' bad');$('#feedback').textContent=correct?'Верно! '+pages[step].why:'Пока не совсем. '+pages[step].why+' Попробуй ещё раз.';if(correct){document.querySelectorAll('[data-lesson-answer]').forEach(x=>x.disabled=true);$('#next').disabled=false}});if($('#draft'))$('#draft').oninput=e=>{user().draft=e.target.value;save()};if($('#previous'))$('#previous').onclick=()=>{step--;render()};if($('#next'))$('#next').onclick=()=>{if(step<2){step++;render();window.scrollTo(0,0)}else{user().completed=true;save();step=0;location.hash='progress'}}}
$('#profile').onchange=e=>{active=e.target.value;quiz=null;step=0;location.hash='home';render()};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
